"""Google sign-in (generated by Shikshya). Google itself is faked (its token endpoint and the id token check); every
check of the flow runs as built: the state and the PKCE verifier, the httpOnly cookie, a verified email, the one-use
code, an existing account losing its password and sign-ins, and a staff account never linked."""
from unittest import mock
from urllib.parse import parse_qs, urlparse

from django.contrib.auth import get_user_model
from django.core import signing
from django.core.cache import cache
from django.test import TestCase, override_settings
from knox.models import AuthToken
from rest_framework.test import APIClient

from .models import GoogleIdentity
from .views import COOKIE, STATE_SALT

GOOGLE = {"GOOGLE_CLIENT_ID": "test-client", "GOOGLE_CLIENT_SECRET": "test-secret", "PUBLIC_URL": "https://app.example.com"}
CLAIMS = {"sub": "google-1", "email": "new@example.com", "email_verified": True, "given_name": "New", "family_name": "User"}


def outcome(response):
    """The fragment the callback sends to /auth/google/done."""
    location = response["Location"]
    assert "/#/auth/google/done#" in location, location
    return {k: v[0] for k, v in parse_qs(location.rsplit("#", 1)[1]).items()}


@override_settings(**GOOGLE)
class GoogleSignInTests(TestCase):
    def setUp(self) -> None:
        cache.clear()
        self.api = APIClient()
        self.claims = dict(CLAIMS)
        post = mock.patch("google_auth.flow.requests.post",
                          return_value=mock.Mock(status_code=200, json=lambda: {"id_token": "test-id-token"}))
        verify = mock.patch("google_auth.flow.id_token.verify_oauth2_token", side_effect=lambda *a, **k: dict(self.claims))
        self.post, self.verify = post.start(), verify.start()
        self.addCleanup(post.stop)
        self.addCleanup(verify.stop)

    def sign_in(self, forged_state: str = ""):
        start = self.api.get("/api/auth/google/")
        self.assertEqual(start.status_code, 302)
        state = forged_state or parse_qs(urlparse(start["Location"]).query)["state"][0]
        self.saved = signing.loads(start.cookies[COOKIE].value, salt=STATE_SALT)
        return self.api.get("/api/auth/google/callback/", {"code": "test-code", "state": state})

    def exchange(self, code: str):
        return self.api.post("/api/auth/google/exchange/", {"code": code}, format="json")

    def test_start_sends_the_browser_to_google_with_pkce_and_a_short_httponly_cookie(self) -> None:
        start = self.api.get("/api/auth/google/")
        url = urlparse(start["Location"])
        query = {k: v[0] for k, v in parse_qs(url.query).items()}
        self.assertEqual((url.scheme, url.netloc), ("https", "accounts.google.com"))
        self.assertEqual(query["redirect_uri"], "https://app.example.com/api/auth/google/callback/")
        self.assertEqual(query["code_challenge_method"], "S256")
        self.assertTrue(query["code_challenge"] and query["state"])
        cookie = start.cookies[COOKIE]
        self.assertTrue(cookie["httponly"])
        self.assertEqual((cookie["max-age"], cookie["path"], cookie["samesite"]), (600, "/api/auth/google/", "Lax"))

    def test_a_new_user_signs_in_once_with_the_code(self) -> None:
        code = outcome(self.sign_in())["code"]
        sent = self.post.call_args.kwargs["data"]
        self.assertEqual((sent["code"], sent["code_verifier"]), ("test-code", self.saved["verifier"]))
        self.assertEqual(self.verify.call_args.kwargs["audience"], "test-client")
        first = self.exchange(code)
        self.assertEqual(first.status_code, 200, first.data)
        self.assertTrue(first.data["token"])
        self.assertEqual(self.exchange(code).status_code, 400)
        user = GoogleIdentity.objects.get(sub="google-1").user
        self.assertEqual((user.email, user.has_usable_password()), ("new@example.com", False))
        self.assertEqual(AuthToken.objects.filter(user=user).count(), 1)

    def test_a_forged_state_is_refused(self) -> None:
        self.assertEqual(outcome(self.sign_in("forged-state"))["error"], "state")
        self.assertFalse(GoogleIdentity.objects.exists())

    def test_a_callback_without_the_cookie_is_refused(self) -> None:
        res = APIClient().get("/api/auth/google/callback/", {"code": "test-code", "state": "anything"})
        self.assertEqual(outcome(res)["error"], "expired")

    def test_a_google_account_without_a_verified_email_is_refused(self) -> None:
        self.claims["email_verified"] = False
        self.assertEqual(outcome(self.sign_in())["error"], "unverified")
        self.assertFalse(GoogleIdentity.objects.exists())

    def test_linking_a_password_account_replaces_its_password_and_ends_its_sign_ins(self) -> None:
        owner = get_user_model().objects.create_user("owner", email="New@Example.com", password="Owner-pass-2026")
        AuthToken.objects.create(owner)
        self.assertTrue(outcome(self.sign_in())["code"])
        owner.refresh_from_db()
        self.assertFalse(owner.has_usable_password())
        self.assertFalse(AuthToken.objects.filter(user=owner).exists())
        self.assertEqual(GoogleIdentity.objects.get(sub="google-1").user, owner)

    def test_a_staff_account_is_never_linked(self) -> None:
        staff = get_user_model().objects.create_user("kitchen", email="new@example.com", password="Staff-pass-2026",
                                                     is_staff=True)
        self.assertEqual(outcome(self.sign_in())["error"], "staff")
        staff.refresh_from_db()
        self.assertTrue(staff.check_password("Staff-pass-2026"))
        self.assertFalse(GoogleIdentity.objects.exists())


@override_settings(**dict(GOOGLE, GOOGLE_CLIENT_ID="", GOOGLE_CLIENT_SECRET=""))
class GoogleNotSetUpTests(TestCase):
    def test_start_without_keys_sends_the_browser_back_with_not_configured(self) -> None:
        cache.clear()
        start = APIClient().get("/api/auth/google/")
        self.assertEqual(start.status_code, 302)
        self.assertEqual(outcome(start)["error"], "not_configured")
